-- Fictional regional sales. Monetary amounts are integer CNY cents.
PRAGMA foreign_keys=ON;
PRAGMA application_id=1381190732;
PRAGMA user_version=1;
CREATE TABLE regions(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE provinces(id INTEGER PRIMARY KEY, region_id INTEGER NOT NULL REFERENCES regions(id), name TEXT NOT NULL);
CREATE TABLE cities(id INTEGER PRIMARY KEY, province_id INTEGER NOT NULL REFERENCES provinces(id), name TEXT NOT NULL);
CREATE TABLE sales_offices(id INTEGER PRIMARY KEY, region_id INTEGER NOT NULL REFERENCES regions(id), city_id INTEGER NOT NULL REFERENCES cities(id), name TEXT NOT NULL);
CREATE TABLE departments(id INTEGER PRIMARY KEY, office_id INTEGER NOT NULL REFERENCES sales_offices(id), name TEXT NOT NULL);
CREATE TABLE employees(id INTEGER PRIMARY KEY, employee_no TEXT NOT NULL UNIQUE, name TEXT NOT NULL, department_id INTEGER REFERENCES departments(id), office_id INTEGER REFERENCES sales_offices(id), region_id INTEGER REFERENCES regions(id), role TEXT NOT NULL CHECK(role IN ('HQ','REGION','OFFICE','SALES')), active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE employee_scopes(id INTEGER PRIMARY KEY, employee_id INTEGER NOT NULL REFERENCES employees(id), scope_type TEXT NOT NULL CHECK(scope_type IN ('ALL','REGION','OFFICE','SELF')), region_id INTEGER REFERENCES regions(id), office_id INTEGER REFERENCES sales_offices(id), CHECK((scope_type IN ('ALL','SELF') AND region_id IS NULL AND office_id IS NULL) OR (scope_type='REGION' AND region_id IS NOT NULL AND office_id IS NULL) OR (scope_type='OFFICE' AND office_id IS NOT NULL AND region_id IS NULL)));
CREATE TABLE sales_channels(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL);
CREATE TABLE customers(id INTEGER PRIMARY KEY, customer_no TEXT NOT NULL UNIQUE, name TEXT NOT NULL, city_id INTEGER NOT NULL REFERENCES cities(id), region_id INTEGER NOT NULL REFERENCES regions(id), office_id INTEGER NOT NULL REFERENCES sales_offices(id), owner_employee_id INTEGER NOT NULL REFERENCES employees(id), channel_id INTEGER NOT NULL REFERENCES sales_channels(id), segment TEXT NOT NULL, acquired_date TEXT NOT NULL);
CREATE TABLE customer_contacts(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT NOT NULL, job_title TEXT NOT NULL);
CREATE TABLE product_categories(id INTEGER PRIMARY KEY, name TEXT NOT NULL);
CREATE TABLE products(id INTEGER PRIMARY KEY, sku TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category_id INTEGER NOT NULL REFERENCES product_categories(id), brand TEXT NOT NULL, list_price_cents INTEGER NOT NULL CHECK(list_price_cents>=0), standard_cost_cents INTEGER NOT NULL CHECK(standard_cost_cents>=0), active INTEGER NOT NULL CHECK(active IN(0,1)));
CREATE TABLE price_lists(id INTEGER PRIMARY KEY, region_id INTEGER NOT NULL REFERENCES regions(id), name TEXT NOT NULL, valid_from TEXT NOT NULL, valid_to TEXT NOT NULL, CHECK(valid_to>=valid_from));
CREATE TABLE product_prices(id INTEGER PRIMARY KEY, price_list_id INTEGER NOT NULL REFERENCES price_lists(id), product_id INTEGER NOT NULL REFERENCES products(id), price_cents INTEGER NOT NULL CHECK(price_cents>=0), UNIQUE(price_list_id,product_id));
CREATE TABLE warehouses(id INTEGER PRIMARY KEY, region_id INTEGER NOT NULL REFERENCES regions(id), office_id INTEGER NOT NULL REFERENCES sales_offices(id), name TEXT NOT NULL);
-- Snapshot only: not a stock movement ledger. Orders do not mutate this balance.
CREATE TABLE inventory_balances(id INTEGER PRIMARY KEY, warehouse_id INTEGER NOT NULL REFERENCES warehouses(id), product_id INTEGER NOT NULL REFERENCES products(id), on_hand INTEGER NOT NULL CHECK(on_hand>=0), reserved INTEGER NOT NULL CHECK(reserved BETWEEN 0 AND on_hand), snapshot_date TEXT NOT NULL, UNIQUE(warehouse_id,product_id,snapshot_date));
-- region/office/owner are immutable sale-time attribution snapshots.
CREATE TABLE sales_orders(id INTEGER PRIMARY KEY, order_no TEXT NOT NULL UNIQUE, customer_id INTEGER NOT NULL REFERENCES customers(id), region_id INTEGER NOT NULL REFERENCES regions(id), office_id INTEGER NOT NULL REFERENCES sales_offices(id), owner_employee_id INTEGER NOT NULL REFERENCES employees(id), channel_id INTEGER NOT NULL REFERENCES sales_channels(id), order_date TEXT NOT NULL, due_date TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','confirmed','partial_shipped','shipped','cancelled')), total_cents INTEGER NOT NULL CHECK(total_cents>=0), CHECK(due_date>=order_date));
CREATE TABLE sales_order_items(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES sales_orders(id), product_id INTEGER NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL CHECK(quantity>0), unit_price_cents INTEGER NOT NULL CHECK(unit_price_cents>=0), unit_cost_cents INTEGER NOT NULL CHECK(unit_cost_cents>=0), discount_cents INTEGER NOT NULL CHECK(discount_cents>=0), net_cents INTEGER NOT NULL CHECK(net_cents=quantity*unit_price_cents-discount_cents AND net_cents>=0));
CREATE TABLE shipments(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES sales_orders(id), warehouse_id INTEGER NOT NULL REFERENCES warehouses(id), shipped_date TEXT NOT NULL, delivered_date TEXT NOT NULL, CHECK(delivered_date>=shipped_date));
CREATE TABLE shipment_items(id INTEGER PRIMARY KEY, shipment_id INTEGER NOT NULL REFERENCES shipments(id), order_item_id INTEGER NOT NULL REFERENCES sales_order_items(id), quantity INTEGER NOT NULL CHECK(quantity>0));
CREATE TABLE sales_returns(id INTEGER PRIMARY KEY, order_id INTEGER NOT NULL REFERENCES sales_orders(id), return_date TEXT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('requested','approved','received','rejected')));
CREATE TABLE sales_return_items(id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL REFERENCES sales_returns(id), order_item_id INTEGER NOT NULL REFERENCES sales_order_items(id), quantity INTEGER NOT NULL CHECK(quantity>0), amount_cents INTEGER NOT NULL CHECK(amount_cents>=0));
CREATE TABLE payments(id INTEGER PRIMARY KEY, customer_id INTEGER NOT NULL REFERENCES customers(id), region_id INTEGER NOT NULL REFERENCES regions(id), office_id INTEGER NOT NULL REFERENCES sales_offices(id), owner_employee_id INTEGER NOT NULL REFERENCES employees(id), paid_date TEXT NOT NULL, method TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0));
CREATE TABLE payment_allocations(id INTEGER PRIMARY KEY, payment_id INTEGER NOT NULL REFERENCES payments(id), order_id INTEGER NOT NULL REFERENCES sales_orders(id), amount_cents INTEGER NOT NULL CHECK(amount_cents>0), UNIQUE(payment_id,order_id));
CREATE TABLE refunds(id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL REFERENCES sales_returns(id), payment_id INTEGER NOT NULL REFERENCES payments(id), refund_date TEXT NOT NULL, amount_cents INTEGER NOT NULL CHECK(amount_cents>0));
CREATE TABLE sales_targets(id INTEGER PRIMARY KEY, month TEXT NOT NULL, region_id INTEGER NOT NULL REFERENCES regions(id), office_id INTEGER NOT NULL REFERENCES sales_offices(id), owner_employee_id INTEGER NOT NULL REFERENCES employees(id), target_cents INTEGER NOT NULL CHECK(target_cents>0), UNIQUE(month,owner_employee_id));
CREATE TABLE schema_comments(table_name TEXT NOT NULL, column_name TEXT NOT NULL, comment_zh TEXT NOT NULL, PRIMARY KEY(table_name,column_name));
CREATE INDEX scopes_employee_idx ON employee_scopes(employee_id);
CREATE INDEX customers_owner_idx ON customers(owner_employee_id,office_id,region_id);
CREATE INDEX orders_region_date_idx ON sales_orders(region_id,order_date);
CREATE INDEX orders_office_date_idx ON sales_orders(office_id,order_date);
CREATE INDEX orders_owner_date_idx ON sales_orders(owner_employee_id,order_date);
CREATE INDEX orders_customer_idx ON sales_orders(customer_id);
CREATE INDEX order_items_order_idx ON sales_order_items(order_id);
CREATE INDEX order_items_product_idx ON sales_order_items(product_id);
CREATE INDEX shipments_order_idx ON shipments(order_id);
CREATE INDEX shipment_items_order_item_idx ON shipment_items(order_item_id);
CREATE INDEX returns_order_idx ON sales_returns(order_id);
CREATE INDEX return_items_return_idx ON sales_return_items(return_id);
CREATE INDEX return_items_order_item_idx ON sales_return_items(order_item_id);
CREATE INDEX payments_owner_idx ON payments(owner_employee_id,office_id,region_id);
CREATE INDEX payments_customer_idx ON payments(customer_id);
CREATE INDEX allocations_order_idx ON payment_allocations(order_id);
CREATE INDEX refunds_return_idx ON refunds(return_id);
CREATE INDEX targets_office_month_idx ON sales_targets(office_id,month);
